def build_infra_height_chart(lang: str = "en") -> str:
    """Return SVG markup for the height comparison chart in the requested language."""
    return HEIGHT_CHARTS.get(lang, HEIGHT_CHARTS["en"])


def build_infra_card(idx: int, lang: str = "en") -> str:
    """Return SVG markup for the landmark architecture card at idx (0..9)."""
    card_list = CARDS.get(lang, CARDS["en"])
    if not (0 <= idx < len(card_list)):
        raise IndexError(f"Card index {idx} out of range (0..{len(card_list)-1})")
    return card_list[idx]


def main() -> None:
    for lang in ("en", "hu"):
        path = ROOT / lang / "infrastructure.html"
        chart_svg = build_infra_height_chart(lang)
        cards = [build_infra_card(i, lang) for i in range(10)]
        update_page_chart(path, chart_svg)
        update_page_cards(path, "building-art", cards)


if __name__ == "__main__":
    main()
